    validated_keyring = _validated_keyring(keyring)

    # Read-only authentication pre-pass.  AuthenticationError is not a
    # per-item outcome: it raises from the batch before any mutation.
    prepared_by_id: dict[str, dict] = {}
    early_errors: dict[str, str] = {}
    for item in validated_items:
