        except AuthenticationError:
            raise
        except (InvalidPruneError, TypeError, ValueError) as exc:
            early_errors[item[ID]] = str(exc)

    reports: list[dict] = []
    for item in validated_items:
        item_id = item[ID]
        if item_id in early_errors:
            reports.append({
                ID: item_id,
                PRUNE_RECEIPT: None,
                PRUNE_ERROR: early_errors[item_id],
            })
            continue
        reports.append(
            _prune_execute_one(item, prepared_by_id[item_id])
