        data[PRUNE_CHECKPOINT], "pruned archive checkpoint"
    )
    if _prune_compact(data, trailing_newline=True) != raw:
        raise _prune_invalid(
            "pruned archive encoding is not the canonical compact form"
        )
    return checkpoint

